namespace ygo {
int stage=0,frames=0,last=0;bool success=false;std::wstring replayFile;
irr::gui::IGUIElement* element(int id){auto* e=mainGame->env->getRootGUIElement()->getElementFromId(id,true);if(!e)throw std::runtime_error("Missing widget "+std::to_string(id));return e;}
void require(bool ok,const char* label){if(!ok)throw std::runtime_error(label);std::cout<<"PASS "<<label<<std::endl;}
void click(int id){irr::SEvent e{};e.EventType=irr::EET_GUI_EVENT;e.GUIEvent.EventType=irr::gui::EGET_BUTTON_CLICKED;e.GUIEvent.Caller=element(id);mainGame->device->postEventFromUser(e);}
void mouseClick(int id){auto r=element(id)->getAbsolutePosition();irr::SEvent e{};e.EventType=irr::EET_MOUSE_INPUT_EVENT;e.MouseInput.X=(r.UpperLeftCorner.X+r.LowerRightCorner.X)/2;e.MouseInput.Y=(r.UpperLeftCorner.Y+r.LowerRightCorner.Y)/2;e.MouseInput.Event=irr::EMIE_MOUSE_MOVED;mainGame->device->postEventFromUser(e);e.MouseInput.Event=irr::EMIE_LMOUSE_PRESSED_DOWN;e.MouseInput.ButtonStates=irr::EMBSM_LEFT;mainGame->device->postEventFromUser(e);e.MouseInput.Event=irr::EMIE_LMOUSE_LEFT_UP;e.MouseInput.ButtonStates=0;mainGame->device->postEventFromUser(e);}
void text(int id,const wchar_t* value){static_cast<irr::gui::IGUIEditBox*>(element(id))->setText(value);}
void select(int id,int index){auto* box=static_cast<irr::gui::IGUIComboBox*>(element(id));box->setSelected(index);irr::SEvent e{};e.EventType=irr::EET_GUI_EVENT;e.GUIEvent.EventType=irr::gui::EGET_COMBO_BOX_CHANGED;e.GUIEvent.Caller=box;mainGame->device->postEventFromUser(e);}
void selectValue(int id,uint32_t value){auto* box=static_cast<irr::gui::IGUIComboBox*>(element(id));for(unsigned i=0;i<box->getItemCount();++i)if(box->getItemData(i)==value){select(id,i);return;}throw std::runtime_error("Missing combo value");}
void search(const wchar_t* code){text(9008,code);click(9001);}
void next(int n){stage=n;last=frames;}
void shot(const char* name){auto* image=mainGame->driver->createScreenShot();if(image){mainGame->driver->writeImageToFile(image,name);image->drop();}}
void DuelEditorGuiTestTick(){try{
 ++frames;if(mainGame->wReplaySave->isVisible() && mainGame->fadingList.empty() && frames>last+20){mainGame->ebRSName->setText(L"自动验证视角录像-v0.1.15");click(BUTTON_REPLAY_SAVE);return;}if(frames>4000)throw std::runtime_error("Perspective GUI timeout");
 if(stage==0 && frames>15){click(BUTTON_TEST_MODE);text(9207,L"0");text(9209,L"0");click(9201);next(1);return;}
 if(stage==1 && DuelEditor::active && element(9003)->isEnabled() && mainGame->dInfo.turn==0){require(mainGame->btnChainAlways->isVisible() && mainGame->btnChainWhenAvail->isVisible(),"Timing controls are available before the first draw phase");require(element(9000)->getRelativePosition().UpperLeftCorner.Y==element(9401)->getRelativePosition().UpperLeftCorner.Y && element(9750)->getRelativePosition().UpperLeftCorner.X>element(9300)->getRelativePosition().LowerRightCorner.X,"Editor, deck order and current player share the bottom-left toolbar");require(element(9000)->getAbsolutePosition().UpperLeftCorner.X>=mainGame->wInfos->getAbsolutePosition().LowerRightCorner.X+6 && element(9750)->getAbsolutePosition().LowerRightCorner.X<element(9007)->getAbsolutePosition().UpperLeftCorner.X,"Bottom toolbar is to the right of the card information pane and clear of transport controls");search(L"89631139");selectValue(9006,LOCATION_MZONE);click(9003);next(2);return;}
 if(stage==2 && frames>last+15 && element(9003)->isEnabled() && mainGame->dField.mzone[0][0]){select(9011,1);search(L"41420027");selectValue(9006,LOCATION_SZONE);click(9003);next(3);return;}
 if(stage==3 && frames>last+15 && element(9003)->isEnabled() && mainGame->dField.szone[1][0]){mainGame->btnChainAlways->setPressed(true);click(BUTTON_CHAIN_ALWAYS);require(DuelEditor::TimingMode(0)==2,"Player one can select all timings independently");click(9750);next(4);return;}
 if(stage==4 && DuelEditor::CurrentView()==1){require(!mainGame->dInfo.isFirst && mainGame->dField.szone[0][0] && mainGame->dField.szone[0][0]->code==41420027 && mainGame->dField.mzone[1][0] && mainGame->dField.mzone[1][0]->code==89631139,"Switching to player two swaps both real card zones and perspective");require(!mainGame->always_chain && DuelEditor::TimingMode(1)==0,"Player two does not inherit player one's all-timing setting");mainGame->btnChainWhenAvail->setPressed(true);click(BUTTON_CHAIN_WHENAVAIL);require(DuelEditor::TimingMode(1)==4,"Player two stores available-timing setting separately");click(9750);next(5);return;}
 if(stage==5 && DuelEditor::CurrentView()==0){require(mainGame->always_chain && !mainGame->chain_when_avail && DuelEditor::TimingMode(1)==4,"Switching back restores player one's setting and retains player two's setting");mainGame->btnChainAlways->setPressed(false);click(BUTTON_CHAIN_ALWAYS);search(L"55144522");selectValue(9006,LOCATION_HAND);click(9003);next(6);return;}
 if(stage==6 && frames>last+15 && element(9003)->isEnabled() && mainGame->dField.hand[0].size()==1){require(mainGame->dInfo.turn==0 && std::wstring(element(9003)->getParent()->getText()).find(L"v0.1.15")!=std::wstring::npos,"Cards are configured in the initial pre-draw editor");click(9004);next(7);return;}
 if(stage==7 && mainGame->dInfo.curMsg==MSG_SELECT_IDLECMD && mainGame->dField.hand[0].size()==1 && (mainGame->dField.hand[0][0]->cmdFlag&COMMAND_ACTIVATE)){mouseClick(9750);next(200);return;}
 if(stage==200 && frames>last+20 && DuelEditor::CurrentView()==1){require(mainGame->dInfo.curMsg==MSG_SELECT_IDLECMD && std::wstring(element(9750)->getText()).find(L"玩家1待处理")!=std::wstring::npos,"Player-one main command remains pending while viewing player two");mainGame->env->setFocus(mainGame->wQuery);mouseClick(BUTTON_CHAIN_ALWAYS);require(DuelEditor::TimingMode(1)==2 && mainGame->env->getFocus()==mainGame->btnChainAlways,"Real mouse click releases hidden prompt focus and changes player-two timing");mouseClick(BUTTON_CHAIN_WHENAVAIL);require(DuelEditor::TimingMode(1)==4 && DuelEditor::TimingMode(0)==0,"Real mouse restores player-two available timing without affecting player one");mouseClick(9000);next(201);return;}
 if(stage==201 && frames>last+15){require(element(9003)->getParent()->isVisible() && SingleMode::paused && DuelEditor::CurrentView()==1,"Real mouse opens editor in player-two view while player-one command is pending");mouseClick(9004);mouseClick(9750);next(202);return;}
 if(stage==202 && frames>last+20 && DuelEditor::CurrentView()==0 && mainGame->dInfo.curMsg==MSG_SELECT_IDLECMD){DuelClient::SetResponseI(5);DuelClient::SendResponse();next(8);return;}
 if(stage==8 && mainGame->dInfo.curMsg==MSG_SELECT_PLACE){unsigned char place[]={0,LOCATION_SZONE,0};DuelClient::SetResponseB(place,3);DuelClient::SendResponse();return;}
 if(stage==8 && mainGame->dInfo.curMsg==MSG_SELECT_CHAIN && std::wstring(element(9750)->getText()).find(L"玩家2待处理")!=std::wstring::npos){require(DuelEditor::CurrentView()==0 && mainGame->dField.activatable_cards.size()>0 && mainGame->dField.activatable_cards[0]->code==41420027,"Real opponent trap effect remains pending while viewing player one");click(BUTTON_NO);next(9);return;}
 if(stage==9 && frames>last+20){require(mainGame->dInfo.curMsg==MSG_SELECT_CHAIN && mainGame->dField.hand[0].empty() && !mainGame->wQuery->isVisible(),"Wrong-view response is blocked and draw effect remains unresolved");mainGame->env->setFocus(mainGame->wQuery);mouseClick(BUTTON_CHAIN_ALWAYS);require(DuelEditor::TimingMode(0)==2 && DuelEditor::TimingMode(1)==4 && mainGame->env->getFocus()==mainGame->btnChainAlways,"Waiting for opponent still allows current player's timing changes independently");mouseClick(BUTTON_CHAIN_ALWAYS);require(DuelEditor::TimingMode(0)==0 && mainGame->dInfo.curMsg==MSG_SELECT_CHAIN,"Changing timing back does not resolve opponent's pending effect");
 bool hovered=false;for(int y=300;y<560 && !hovered;y+=5)for(int x=330;x<950 && !hovered;x+=5){mainGame->dField.GetHoverField(x,y);if(mainGame->dField.hovered_controler==0 && mainGame->dField.hovered_location==LOCATION_MZONE && mainGame->dField.hovered_sequence==0){irr::SEvent move{};move.EventType=irr::EET_MOUSE_INPUT_EVENT;move.MouseInput.Event=irr::EMIE_MOUSE_MOVED;auto rect=mainGame->Resize(x,y,x+1,y+1);move.MouseInput.X=rect.UpperLeftCorner.X;move.MouseInput.Y=rect.UpperLeftCorner.Y;mainGame->device->postEventFromUser(move);hovered=true;}}require(hovered && mainGame->showingcode==89631139 && mainGame->dInfo.curMsg==MSG_SELECT_CHAIN,"Mouse hover still displays real card information while opponent effect waits");
 irr::SEvent tabs{};tabs.EventType=irr::EET_GUI_EVENT;tabs.GUIEvent.EventType=irr::gui::EGET_TAB_CHANGED;tabs.GUIEvent.Caller=mainGame->wInfos;require(!DuelEditor::OnEvent(tabs),"Information pane navigation remains available while opponent waits");shot("../opponent-pending-preview.png");require(element(9000)->isEnabled(),"Editor button stays available during an opponent pending effect");mouseClick(9000);next(90);return;}
 if(stage==90 && frames>last+15){require(element(9003)->getParent()->isVisible() && SingleMode::paused && mainGame->dInfo.curMsg==MSG_SELECT_CHAIN && mainGame->dField.hand[0].empty(),"Editor opens and pauses during opponent pending effect without resolving it");click(9004);click(9750);next(10);return;}
 if(stage==10 && frames>last+25 && DuelEditor::CurrentView()==1 && mainGame->dInfo.curMsg==MSG_SELECT_CHAIN && mainGame->wQuery->isVisible()){require(mainGame->dField.activatable_cards.size()>0 && mainGame->dField.activatable_cards[0]->controler==0,"Switching to player two restores their genuine activation decision");shot("../player-two-decision-preview.png");click(9000);next(100);return;}
 if(stage==100 && frames>last+15){require(element(9003)->getParent()->isVisible() && SingleMode::paused && mainGame->dInfo.curMsg==MSG_SELECT_CHAIN,"Editor also opens on the deciding player while their real effect choice is pending");click(BUTTON_NO);next(101);return;}
 if(stage==101 && frames>last+15){require(mainGame->dInfo.curMsg==MSG_SELECT_CHAIN && mainGame->dField.hand[1].empty(),"Opening editor does not accept underlying activation buttons or resolve the pending effect");click(9004);next(102);return;}
 if(stage==102 && frames>last+15){require(mainGame->dInfo.curMsg==MSG_SELECT_CHAIN && mainGame->wQuery->isVisible(),"Closing editor restores the same pending activation choice");click(9403);text(9502,L"自动验证视角时点-v0.1.15");click(9503);next(110);return;}
 if(stage==110 && std::wstring(element(9505)->getText()).find(L"已保存")!=std::wstring::npos){require(DuelEditor::CurrentView()==1,"Pending player-two decision saves without switching perspective");click(9506);click(9403);static_cast<irr::gui::IGUIListBox*>(element(9501))->setSelected(0);click(9504);next(111);return;}
 if(stage==111 && std::wstring(element(9505)->getText()).find(L"已读取")!=std::wstring::npos && mainGame->dInfo.curMsg==MSG_SELECT_CHAIN && mainGame->wQuery->isVisible()){require(DuelEditor::CurrentView()==1 && !mainGame->dInfo.isFirst && mainGame->dField.activatable_cards[0]->controler==0,"Loading pending decision preserves player-two view and exact selectable effect");click(9401);next(112);return;}
 if(stage==112 && frames>last+25 && !SingleMode::paused && mainGame->dInfo.curMsg==MSG_SELECT_CHAIN){click(BUTTON_NO);next(11);return;}
 if(stage==11 && mainGame->dInfo.curMsg==MSG_SELECT_IDLECMD && mainGame->dField.hand[1].size()==2){require(mainGame->dField.mzone[1][0] && mainGame->dField.szone[0][0] && mainGame->dField.grave[1].size()==1,"Player two's explicit decline resumes original draw effect without activating their trap");require(DuelEditor::TimingMode(0)==0 && DuelEditor::TimingMode(1)==4,"Timings retain their independent values after real effect processing");click(9750);next(12);return;}
 if(stage==12 && DuelEditor::CurrentView()==0 && mainGame->dField.hand[0].size()==2){click(BUTTON_LEAVE_GAME);next(13);return;}
 if(stage==13 && !DuelEditor::active && !mainGame->dInfo.isStarted && mainGame->wMainMenu->isVisible() && mainGame->fadingList.empty()){replayFile=L"./replay/"+std::wstring(mainGame->ebRSName->getText())+L".yrp";click(BUTTON_REPLAY_MODE);next(14);return;}
 if(stage==14 && frames>last+15){mainGame->open_file=true;BufferIO::CopyWideString(replayFile.c_str(),mainGame->open_file_name);click(BUTTON_LOAD_REPLAY);next(15);return;}
 if(stage==15 && mainGame->dInfo.isReplay && mainGame->wMessage->isVisible()){require(mainGame->dField.hand[0].size()==2 && mainGame->dField.mzone[0][0] && mainGame->dField.szone[1][0] && mainGame->dField.grave[0].size()==1,"Real replay reproduces opponent's manual response after perspective switching");ReplayMode::StopReplay(true);success=true;mainGame->device->closeDevice();}
 }catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<" stage="<<stage<<" msg="<<int(mainGame->dInfo.curMsg)<<" hands="<<mainGame->dField.hand[0].size()<<","<<mainGame->dField.hand[1].size()<<std::endl;shot("../perspective-failure-preview.png");SingleMode::StopPlay(true);mainGame->device->closeDevice();}}
}
int main(){using namespace ygo;std::setlocale(LC_CTYPE,".UTF-8");try{mainGame=new Game();require(mainGame->Initialize(),"Production OpenGL client initializes");ShowWindow(mainGame->hWnd,SW_HIDE);mainGame->MainLoop();if(success)std::cout<<"SUCCESS independent player timing, deferred opponent decision, perspective and real replay"<<std::endl;return success?0:1;}catch(const std::exception& e){std::cerr<<e.what()<<std::endl;return 1;}}
